import { Component, OnInit } from '@angular/core';
import { FournisseurService } from 'src/app/services/fournisseur.service';
import { Medicament } from 'src/app/models/Medicament';
import { Fournisseur } from 'src/app/models/Fournisseur';

@Component({
  selector: 'app-fournisseur-list',
  templateUrl: './fournisseur-list.component.html',
  styleUrls: ['./fournisseur-list.component.css']
})
export class FournisseurListComponent implements OnInit {
  fournisseurs: Fournisseur[] = [];
  medicaments: Medicament[] = [];
  searchTerm: string = '';
  filteredFournisseurs: Fournisseur[] = [];  // Used to store filtered suppliers
  cheapestMedicaments: { fournisseur: Fournisseur, medicament: Medicament }[] = [];

  constructor(private fournisseurService: FournisseurService) { }

  ngOnInit(): void {
    this.getAllFournisseurs();
  }

  // Get all suppliers
  getAllFournisseurs(): void {
    this.fournisseurService.getAllFournisseurs().subscribe(data => {
      this.fournisseurs = data;
      this.filteredFournisseurs = data;  // Set filteredFournisseurs to all suppliers initially
    });
  }

  // Search for suppliers by medicament
  searchFournisseursByMedicament(): void {
    if (this.searchTerm.trim() === '') {
      // If no search term, show all suppliers
      this.filteredFournisseurs = this.fournisseurs;
    } else {
      this.fournisseurService.searchFournisseursByMedicament(this.searchTerm).subscribe(data => {
        this.cheapestMedicaments = [];

        // Loop through each fournisseur and find the medicament
        data.forEach(fournisseur => {
          this.fournisseurService.getMedicamentsByFournisseur(fournisseur.idfournisseur).subscribe(medicaments => {
            const medicament = medicaments.find(med => med.nom.toLowerCase() === this.searchTerm.toLowerCase());
            if (medicament) {
              // Add the fournisseur and its medicament to the cheapestMedicaments array
              this.cheapestMedicaments.push({ fournisseur, medicament });

              // Sort the list by price (ascending)
              this.cheapestMedicaments.sort((a, b) => a.medicament.prix - b.medicament.prix);
            }
          });
        });
        // Set the filtered list based on the searched suppliers
        this.filteredFournisseurs = data;
      });
    }
  }
}
<div class="search-bar">
    <input type="text" [(ngModel)]="searchTerm" (input)="searchFournisseursByMedicament()" placeholder="Rechercher un médicament" />
</div>

<h2>Liste des Fournisseurs</h2>
<ul>
    <li *ngFor="let item of cheapestMedicaments">
        <a [routerLink]="['/fournisseur', item.fournisseur.idfournisseur]">
            {{ item.fournisseur.nom }} ({{ item.fournisseur.contact }})
        </a>
        <!-- Show the price of the medicament under the supplier name -->
        <p>Prix de {{ searchTerm }}: {{ item.medicament.prix }}€</p>
        <button [routerLink]="['/medicaments', item.fournisseur.idfournisseur]">Voir Médicaments</button>
    </li>
</ul>
